/*! js di header */
function activeStickyKit(){$("[data-sticky_column]").stick_in_parent({parent:"[data-sticky_parent]",offset_top:15}),$("[data-sticky_column]").on("sticky_kit:bottom",function(t){$(this).parent().css("position","static")}).on("sticky_kit:unbottom",function(t){$(this).parent().css("position","relative")})}function detachStickyKit(){$("[data-sticky_column]").trigger("sticky_kit:detach")}function resize(){$(window).width()<769?detachStickyKit():activeStickyKit()}function logoutAccount(){showLoading(),SessionStorage.clear(),window.location.assign("/user/logout")}
$(document).ready(function(){resize(),$(window).resize(function(){resize()}),$("[data-sticky_stepDashboard]").stick_in_parent({parent:"[data-sticky_parent]",offset_top:0})});

$(function(){ new HeaderCmpnt; });

$(document).ready(function() {
	// sidebar mobile
	$('body').on('click', '.btn-new-summary-btm', function() {
		var parent = $(this).parents('.new-summary-btm');

		if(parent.hasClass('open-sidebar')) {
			parent.removeClass('open-sidebar') 
			$('body').removeClass('disable-overflow');
		}
		else {
			parent.addClass('open-sidebar');
			$('body').addClass('disable-overflow');
		}
		
	});

	var _pathName = window.location.pathname;
	_pathName =_pathName.replace(/\//g,'');
	$('#navbarSupportedContent li').removeClass('active');
	switch(_pathName){
		case 'dashboard-userdashboarddashboard':
		case 'dashboard':
			$('#navbarSupportedContent li.nav-item').eq(0).addClass('active');
		break;
		case 'dashboard-userdashboardleads':
		case 'dashboard-userdashboardleads-detail':
			$('#navbarSupportedContent li.nav-item').eq(1).addClass('active');
		break;	
		case 'dashboard-userdashboardleads-settlement':
			$('#navbarSupportedContent li.nav-item').eq(2).addClass('active');
		break;
		case 'dashboard-userdashboardpromocode':
		case 'dashboard-userdashboardpromocode-new':
		case 'dashboard-userdashboardpromocode-edit':
			$('#navbarSupportedContent li.nav-item').eq(3).addClass('active');
		break;		
		case 'dashboard-userdashboardmedia':
			$('#navbarSupportedContent li.nav-item').eq(4).addClass('active');
		break;
		case 'dashboard-userdashboardprofile':
		case 'dashboard-userdashboardlocation':
		case 'dashboard-userdashboardworking-hour':
		case 'dashboard-userdashboardsocial-media':
			$('#navbarSupportedContent li.nav-item ul li.dropdown-item').eq(0).addClass('active');
		break;
		case 'dashboard-userdashboardtimeline':
			$('#navbarSupportedContent li.nav-item ul li.dropdown-item').eq(1).addClass('active');
		break;
		case 'dashboard-userdashboardhistory':
			$('#navbarSupportedContent li.nav-item ul li.dropdown-item').eq(2).addClass('active');
		break;
		case 'dashboard-userdashboardchange-password':
			$('#navbarSupportedContent li.nav-item ul li.dropdown-item').eq(3).addClass('active');
		break;
	}

});

